365	  private func unifiedBody(_ diff: UnifiedDiff) -> some View {
366	    // Vertical-only scroll, eager `VStack` (not `LazyVStack`): the rows soft-wrap via
367	    // `fixedSize(vertical:)`, and a lazy stack caches a bad height estimate for not-yet-materialised
368	    // wrapping rows — leaving a blank band in the middle of a tall diff until you scroll it into
369	    // view. `UnifiedDiff.parse`'s 2000-line cap bounds the row count, so laying them all out up
370	    // front is affordable and gap-free.
371	    //
372	    // This is NOT a general rule against lazy stacks, and `HistoryPanel` deliberately uses one: its
373	    // rows are single-line `lineLimit(1)`, so their height is known before layout and the estimate a
374	    // lazy stack caches is correct. The distinction is soft-wrapping vs fixed-height rows, not
375	    // "diffs vs history" — which matters because History's row count is unbounded by anything as
376	    // tight as 2000 lines, and building all of it eagerly is what produced a 2-second App Hang
377	    // (WORKROOM-2B).
378	    ScrollView(.vertical) {
379	      VStack(alignment: .leading, spacing: 0) {
380	        if let from = diff.renamedFrom {
381	          headerNote("Renamed from \(from)")
382	        }
383	        ForEach(Array(diff.hunks.enumerated()), id: \.offset) { _, hunk in
384	          hunkHeader(hunk.header)
385	          ForEach(Array(hunk.lines.enumerated()), id: \.offset) { _, line in
386	            lineRow(line)
387	          }
388	        }
389	        if diff.truncated {
390	          headerNote("Diff truncated — file too large to show in full.")
391	        }
392	      }
393	      .frame(minWidth: 0, maxWidth: .infinity, alignment: .leading)
394	      .padding(.vertical, 4)
395	    }
396	  }
