428	  private func sideBySideRow(_ row: UnifiedDiff.SideBySideRow) -> some View {
429	    // `.top` so each side's gutter aligns to the first visual line when the taller side wraps. The
430	    // add/remove/absent fills are painted as a full-height background *layer* (two equal halves), not
431	    // per-cell: a bare cell background collapses to the gutter line under `.top` alignment, so a
432	    // short side opposite a multi-line wrapped side would only tint its first line. The background
433	    // matches the row's height (the taller side), so both halves always span the full row.
434	    HStack(alignment: .top, spacing: 0) {
435	      sideCell(row.left, side: .left)
436	      Divider()
437	      sideCell(row.right, side: .right)
438	    }
439	    .padding(.vertical, 2)  // a little line breathing room (matches the unified rows)
440	    .frame(maxWidth: .infinity, alignment: .leading)
441	    .background(
442	      HStack(spacing: 0) {
443	        sideHalfFill(row.left).frame(maxWidth: .infinity)
444	        sideHalfFill(row.right).frame(maxWidth: .infinity)
445	      }
446	    )
447	  }
